\label{twosets}For a regular Borel measure $\mu $ on $\partial \Omega $, we
denote by
\begin{equation}
\Gamma _{\mu }^{\infty }:=\{z\in \partial \Omega :\;\mu (B(z,r)\cap \partial
\Omega )=\infty \;\forall \;r>0\}  \label{GI}
\end{equation} 
the relatively closed subset of $\partial \Omega $ on which the measure $\mu
$ is \emph{locally infinite}. The complement of $\Gamma _{\mu }^{\infty }$
denoted by
\begin{equation}
\Gamma _{\mu }:=\partial \Omega \setminus \Gamma _{\mu }^{\infty }=\{z\in
\partial \Omega :\;\exists \;r>0:\;\mu (B(z,r)\cap \partial \Omega )<\infty
\}  \label{LF}
\end{equation} 
is the relatively open subset of $\partial \Omega $ on which the measure $ 
\mu $ is \emph{locally finite}. We will also call the part $\Gamma _{\mu }$
the domain of the measure $\mu $ and denote $D(\mu )=\Gamma _{\mu }$.

\emph{It is clear that by definition, if }$\mu (\partial \Omega )<\infty $ 
\emph{, then }$D(\mu )=\partial \Omega $\emph{\ so that }$\Gamma _{\mu
}^{\infty }=\emptyset $\emph{. }

\emph{Next, let $0<a_{n+1}<b_{n+1}<a_{n}<1$ ($n\in {\mathbb{N}}$) be such
that $\lim_{n\rightarrow \infty }a_{n}=0$. Let
\begin{equation*}
\Omega :=\left\{ (x,y)\in (0,1)\times (0,1)\setminus \bigcup_{n\in {\mathbb{N 
}}}[a_{n},b_{n}]\times \left[ \frac{1}{2},1\right] \right\} \subset \mathbb{R 
}^{2}.
\end{equation*} 
Let $\sigma :=\mathcal{H}^{1}|_{\partial \Omega }$. It is easy to see that }$ 
\sigma (\partial \Omega )$\emph{$=\infty $ and that }$\Gamma _{\sigma
}^{\infty }=\{0\}\times \lbrack 1/2,1]$\emph{. }

\label{snow}\emph{Let $\Omega \subset {\mathbb{R}}^{2}$ be the Koch
snowflake (see Figure 1) and let }$\sigma :=\mathcal{H}^{1}|_{\partial
\Omega }$\emph{. Then }$\Gamma _{\sigma }^{\infty }=\partial \Omega $\emph{\
so that }$\Gamma _{\sigma }=D(\sigma )=\emptyset $\emph{. It is well-known
that }$\partial \Omega $ \emph{has} \emph{Hausdorff dimension equal to $ 
d:=\ln (4)/\ln (3),$ see \cite{Wal}. In this case, the }$d$\emph{-dimensional 
} \emph{Hausdorff measure of} $\partial \Omega $ \emph{is finite}, $\mathcal{ 
H}^{d}(\partial \Omega )<\infty ,$\emph{\ so that} $\Gamma _{\mathcal{H} 
^{d}}^{\infty }=\emptyset $\emph{\ and }$D(\mathcal{H}^{d})=\Gamma _{ 
\mathcal{H}^{d}}=\partial \Omega $\emph{.}

Let $d\in \lbrack 0,N]$ and let $\mu $ be a regular Borel measure on $ 
\partial \Omega $.

\begin{enumerate}
\item We say that $\mu $ is an \emph{upper $d$-Ahlfors measure} if there
exists a constant $C_{2}>0$ such that for every $x\in \partial \Omega $ and
every $r\in (0,1]$, one has
\begin{equation*}
\mu (B(x,r)\cap \partial \Omega )\leq C_{2}r^{d}.
\end{equation*}

\item We say that $\mu $ is a \emph{lower $d$-Ahlfors measure} if there
exists a constant $C_{1}>0$ such that for every $x\in \partial \Omega $ and
every $r\in (0,1]$, one has
\begin{equation*}
\mu (B(x,r)\cap \partial \Omega )\geq C_{1}r^{d}.
\end{equation*}
\end{enumerate}

\label{def_dset}Let $F$ be a closed set in ${\mathbb{R}}^{N}$. We say that $ 
F $ is a $d$-set for some $d\in (0,N]$ in the sense that there exist a Borel
measure $\mu $ on $F$ and some constants $C_{2}>C_{1}>0$ such that
\begin{equation}
C_{1}r^{d}\leq \mu (F\cap B(x,r))\leq C_{2}r^{d}\;\text{ for all }x\in F
\text{ and all }r\in (0,1],  \label{hausdor}
\end{equation} 
where $B(x,r)$ is the Euclidean metric ball. Notice that a measure
satisfying \eqref{hausdor} is called a $d$-Ahlfors measure.

There is a constant $C=C(N)>0$ such that for every function $u\in
W^{1,1}(\Omega )\cap C(\overline{\Omega })$,
\begin{equation}
\Vert u\Vert _{\frac{N}{N-1},\Omega }\leq C(N)\left( \Vert \nabla u\Vert
_{1,\Omega }+\Vert u\Vert _{L^{1}(\partial \Omega ,\sigma )}\right) .
\label{M1}
\end{equation} 
In the inequality \eqref{M1}, the constant $C(N)$ is exactly the so called
isoperimetric constant.

(\cite[Corollary 2.11.2]{MP})\label{CM2} Let $1\leq p<\infty $ and $p^{\star
}:=pN/(N-1)$. There is a constant $C=C(N,p,\Omega )>0$ such that for every $ 
u\in W^{1,p}(\Omega )\cap C(\overline{\Omega })$,
\begin{equation}
\Vert u\Vert _{p^{\star },\Omega }^{p}\leq C\left( \Vert \nabla u\Vert
_{p,\Omega }^{p}+\Vert u\Vert _{L^{p}(\partial \Omega ,\sigma )}^{p}\right) .
\label{M2-N-1}
\end{equation}

The \emph{relative capacity} $Cap_{2,\Omega }$ with respect to $\Omega $ is
defined for sets $A\subset \overline{\Omega }$ by
\begin{equation*}
Cap_{2,\Omega }(A):=\inf \left\{ \Vert u\Vert _{W^{1,2}(\Omega )}^{2}\;:\; 
\begin{array}{l}
u\in {\mathcal{W}}^{1,2}(\Omega ),\;\exists \;O\subset {\mathbb{R}}^{N}\text{
open,} \\
A\subset O\text{ and }u\geq 1\text{ a.e. on }\Omega \cap O 
\end{array} 
\right\} .
\end{equation*}

\begin{itemize}
\item A set $P\subset \overline{\Omega }$ is called $Cap_{2,\Omega }$\emph{ 
-polar} if $Cap_{2,\Omega }(P)=0$.

\item We say that a property holds $Cap_{2,\Omega }$-quasi everywhere
(briefly q.e.) on a set $A\subset \overline{\Omega }$, if there exists a $ 
Cap_{2,\Omega }$-polar set $P$ such that the property holds for all $x\in
A\setminus P$.

\item A function $u$ is called $Cap_{2,\Omega }$-quasi continuous on a set $ 
A\subset \overline{\Omega }$ if for all $\varepsilon >0$ there exists an
open set $O$ in the metric space $\overline{\Omega }$ such that $ 
Cap_{2,\Omega }(O)\leq \varepsilon $ and $u$ restricted to $A\setminus O$ is
continuous.
\end{itemize}

\label{lower-semi} The following assertions are equivalent.

\begin{enumerate}
\item[(i)] The operator $R:\;W_{2,2}^{1}(\Omega ,\partial \Omega ,\mu
)\rightarrow L^{2}(\Omega )$, $u\mapsto u|_{\Omega}$ is injective.

\item[(ii)] The set $\Gamma _{\mu }$ is $\func{Cap}_{2,\Omega }$-admissible
with respect to $\mu $.

\item[(iii)] The bilinear form $\mathcal{A}_{\Theta ,\mu }$ is closed on $ 
L^{2}(\Omega )$.
\end{enumerate}

\label{3prop} Let $\Gamma _{\mu }$ be $\func{Cap}_{2,\Omega }$-admissible
with respect to $\mu $. Assume that either $\mu =\sigma $ or that
\begin{equation}
\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )\hookrightarrow
L^{2q}(\Omega )\mbox{ for some }q=q\left( N,\Omega \right) >1\;\mbox{ if } 
\;\mu \neq \sigma .  \label{CI-mu}
\end{equation} 
Then the following assertions hold.

\begin{enumerate}
\item The operator $-A_{\Theta ,\mu }$ generates a strongly continuous
semigroup $(e^{-tA_{\Theta ,\mu }})_{t\geq 0}$ of contractions on $ 
L^{2}(\Omega ) $ which can be extended to contraction strongly continuous
semigroups on $L^{p}(\Omega )$ for every $p\in \lbrack 1,\infty )$.

\item The operator $A_{\Theta ,\mu }$ has a compact resolvent, and hence has
a discrete spectrum. The spectrum of $A_{\Theta ,\mu }$ is an increasing
sequence of real numbers $0\leq \lambda _{1}<\lambda _{2}<\cdots <\lambda
_{n}<\dots ,$ that converges to $+\infty $. Moreover, if $u_{n}$ is an
eigenfunction associated with $\lambda _{n}$, then $u_{n}\in D\left(
A_{\Theta ,\mu }\right) \cap L^{\infty }(\Omega )$.

\item Assume also that either $\func{Cap}_{2,\Omega }(\Gamma _{\mu }^{\infty
})>0$ or $\mu (\Gamma _{\mu })>0$. Then $0\in \rho (A_{\Theta ,\mu }),$ the
resolvent set of $A_{\Theta ,\mu }$, and there exists a constant $C>0$ such
that, for every $u\in \mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega
,\mu )$,
\begin{equation}
\Vert u\Vert _{2,\Omega }^{2}\leq C\mathcal{A}_{\Theta ,\mu }(u,u).
\label{eq-coer}
\end{equation}

\item Denoting the generator of the semigroup on $L^{p}(\Omega )$ by $ 
A_{p,\Theta ,\mu }$, so that $A_{\Theta ,\mu }=A_{2,\Theta ,\mu }$, then the
spectrum of $A_{p,\Theta ,\mu }$ is independent of $p$. The spectral bound
\begin{equation*}
s\left( A_{p,\Theta ,\mu }\right) =\inf \left\{ \func{Re}\lambda :\lambda
\in \sigma \left( A_{p,\Theta ,\mu }\right) \right\}
\end{equation*} 
of $A_{p,\Theta ,\mu }$ is an algebraically simple eigenvalue. It is the
only eigenvalue having a positive eigenfunction.

\item For each $\theta \in (0,1]$, there holds $D(A_{\Theta ,\mu }^{\theta
})\subset L^{\infty }\left( \Omega \right) $ provided that $\theta >\gamma .$
Here, $\gamma =N/2$ if $\mu =\sigma $ and $\gamma =q/2(q-1)$ if $\mu \neq
\sigma $.
\end{enumerate}

\label{weak} Let $u_{0}\in L^{2}(\Omega )$ be given and assume (H2) holds
for some $p>1$. The function $u$ is said to be a \emph{weak} solution of ( 
\ref{1.1})-(\ref{1.3}) if, for a.e. $t\in \left( 0,T\right) ,$ for any $T>0$ 
, the following properties are valid:

\begin{itemize}
\item Regularity: 
\begin{equation}
\left\{
\begin{array}{l}
u\in L^{\infty }\left( 0,T;L^{2}\left( \Omega \right) \right) \cap
L^{p}\left( \left( 0,T\right) \times \Omega \right) \cap L^{2}(0,T;\mathcal{V 
}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )), \\
\partial _{t}u\in L^{2}(0,T;(\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial
\Omega ,\mu ))^{\ast })+L^{p^{^{\prime }}}\left( \left( 0,T\right) \times
\Omega \right) , 
\end{array} 
\right.  \label{reg_weak}
\end{equation} 
where $p^{^{\prime }}=p/\left( p-1\right) .$

\item Variational identity: for the weak solutions the following equality 
\begin{equation}
\left\langle \partial _{t}u\left( t\right) ,\xi \right\rangle +\mathcal{A} 
_{\Theta ,\mu }(u\left( t\right) ,\xi )+\left\langle f\left( u\left(
t\right) \right) ,\xi \right\rangle =0  \label{de_form}
\end{equation} 
holds for all $\xi \in \mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega
,\mu )\cap L^{p}\left( \Omega \right) ,$ a.e. $t\in \left( 0,T\right) $.
Finally, we have, in the space $L^{2}\left( \Omega \right) ,$ $u\left(
0\right) =u_{0}$ almost everywhere.

\item Energy identity: weak solutions satisfy the following identity 
\begin{equation}
\frac{1}{2}\left\Vert u\left( t\right) \right\Vert _{2,\Omega
}^{2}+\int_{0}^{t}\left[ \mathcal{A}_{\Theta ,\mu }\left( u\left( s\right)
,u\left( s\right) \right) +\left\langle f\left( u\left( s\right) \right)
,u\left( s\right) \right\rangle \right] ds=\frac{1}{2}\left\Vert u\left(
0\right) \right\Vert _{2,\Omega }^{2}.  \label{en_id}
\end{equation}
\end{itemize}

\label{strong} Let $u_0\in L^\infty(\Omega)$ be given. A weak solution $u$
is "\emph{strong"} if, in addition, it fulfills the regularity properties: 
\begin{equation}
u\in W_{\text{loc}}^{1,\infty }((0,T];L^{2}(\Omega ))\cap C\left( \left[ 0,T 
\right] ;L^{\infty }\left( \Omega \right) \right) ,  \label{time_reg}
\end{equation} 
such that $u\left( t\right) \in D(A_{\Theta ,\mu }),$ a.e. $t\in \left(
0,T\right) ,$ for any $T>0.$

\emph{Step 1} (Local existence). Let $u_{0}\in L^{\infty }\left( \Omega
\right) \subset L^{2}\left( \Omega \right) =\overline{D(\mathcal{A}_{\Theta
,\mu })}^{L^{2}(\Omega )}=\overline{D({\varphi }_{\Theta ,\mu })} 
^{L^{2}(\Omega )}$. By Theorem \ref{lower-semi}, ${\varphi }_{\Theta ,\mu }$
is proper, convex and lower semi-continuous on the Hilbert space $ 
L^{2}(\Omega )$ (cf. also \cite[Theorem 5.2]{W3}). Moreover, from Theorem  
\ref{3prop} we know that $-A_{\Theta ,\mu }$ ($=-\partial \varphi _{\Theta
,\mu }$) generates a strongly continuous (linear) semigroup $(e^{-tA_{\Theta
,\mu }})_{t\geq 0}$ of contraction operators on $L^{2}(\Omega )$. Finally,
by Theorem \ref{SGbis} (Appendix), $e^{-tA_{\Theta ,\mu }}$ is non-expansive
on $L^{\infty }\left( \Omega \right) ,$
\begin{equation}
\left\Vert e^{-tA_{\Theta ,\mu }}u_{0}\right\Vert _{\infty ,\Omega }\leq
\left\Vert u_{0}\right\Vert _{\infty ,\Omega },\text{ }t\geq 0\text{ and } 
u_{0}\in L^{\infty }\left( \Omega \right) ,  \label{nonexp}
\end{equation} 
and $A_{\Theta ,\mu }=\partial \varphi _{\Theta ,\mu }$ is strongly
accretive by Theorem \ref{3prop}-(c), see (\ref{eq-coer}). Thus, we can give
an operator theoretic version of the original problem (\ref{1.1})-(\ref{1.3} 
): 
\begin{equation}
\partial _{t}u=-A_{\Theta ,\mu }u-f\left( u\right) ,  \label{op_v}
\end{equation} 
with $f$ as a locally Lipschitz perturbation of a monotone operator, on
account of the fact that $f\in C_{\text{loc}}^{1}\left( \mathbb{R}\right) $.
We construct the (locally-defined) strong solution by a fixed point
argument. To this end, fix $0<T^{\ast }\leq T$, consider the space
\begin{equation*}
\mathcal{X}_{T^{\ast },R^{\ast }}\equiv \left\{ u\in C\left( \left[
0,T^{\ast }\right] ;L^{\infty }\left( \Omega \right) \right) :\left\Vert
u\left( t\right) \right\Vert _{\infty ,\Omega }\leq R^{\ast }\right\}
\end{equation*} 
and define the following mapping 
\begin{equation}
\Sigma \left( u\right) \left( t\right) =e^{-tA_{\Theta ,\mu
}}u_{0}-\int_{0}^{t}e^{-\left( t-s\right) A_{\Theta ,\mu }}f\left( u\left(
s\right) \right) ds,\text{ }t\in \left[ 0,T^{\ast }\right] .  \label{mapping}
\end{equation} 
Note that $\mathcal{X}_{T^{\ast },R^{\ast }}$, when endowed with the norm of
$C\left( \left[ 0,T^{\ast }\right] ;L^{\infty }\left( \Omega \right) \right)
,$ is a closed subset of $C\left( \left[ 0,T^{\ast }\right] ;L^{\infty
}\left( \Omega \right) \right) ,$ and since $f$ is continuously
differentiable, $\Sigma \left( u\right) \left( t\right) $ is continuous on $ 
\left[ 0,T^{\ast }\right] $. We will show that, by properly choosing $ 
T^{\ast },R^{\ast }>0$, $\Sigma :\mathcal{X}_{T^{\ast },R^{\ast
}}\rightarrow \mathcal{X}_{T^{\ast },R^{\ast }}$ is a contraction mapping
with respect to the metric induced by the norm of $C\left( \left[ 0,T^{\ast } 
\right] ;L^{\infty }\left( \Omega \right) \right) .$ The appropriate choices
for $T^{\ast },R^{\ast }>0$ will be specified below. First, we show that $ 
u\in \mathcal{X}_{T^{\ast },R^{\ast }}$ implies that $\Sigma \left( u\right)
\in \mathcal{X}_{T^{\ast },R^{\ast }}$, that is, $\Sigma $ maps $\mathcal{X} 
_{T^{\ast },R^{\ast }}$ to itself. From (\ref{nonexp}) and the fact that $ 
f\in C_{\text{loc}}^{1}\left( \mathbb{R}\right) $, we observe that the
mapping $\Sigma $\ satisfies the following estimate 
\begin{align*}
\left\Vert \Sigma \left( u\left( t\right) \right) \right\Vert _{\infty
,\Omega }& \leq \left\Vert u_{0}\right\Vert _{\infty ,\Omega
}+\int_{0}^{t}\left\Vert e^{-\left( t-s\right) A_{\Theta ,\mu }}\left(
f\left( 0\right) +\left( f\left( u\left( s\right) \right) -f\left( 0\right)
\right) \right) \right\Vert _{\infty ,\Omega }ds \\
& \leq \left\Vert u_{0}\right\Vert _{\infty ,\Omega }+t\left( \left\vert
f\left( 0\right) \right\vert +Q_{f^{^{\prime }}}\left( R^{\ast }\right)
R^{\ast }\right) ,
\end{align*} 
for some positive continuous function $Q_{f^{^{\prime }}}$ which depends
only on the size of the nonlinearity $f^{^{\prime }}$. Thus, provided that
we set $R^{\ast }\geq 2\left\Vert u_{0}\right\Vert _{\infty ,\Omega }$, we
can find a sufficiently small time $T^{\ast }>0$ such that
\begin{equation}
2T^{\ast }\left( \left\vert f\left( 0\right) \right\vert +Q_{f^{^{\prime
}}}\left( R^{\ast }\right) R^{\ast }\right) \leq R^{\ast },  \label{3.21time}
\end{equation} 
in which case $\Sigma \left( u\left( t\right) \right) \in \mathcal{X} 
_{T^{\ast },R^{\ast }}$, for any $u\left( t\right) \in \mathcal{X}_{T^{\ast
},R^{\ast }}.$ Next, we show that by possibly choosing $T^{\ast }>0$
smaller, $\Sigma :\mathcal{X}_{T^{\ast },R^{\ast }}\rightarrow \mathcal{X} 
_{T^{\ast },R^{\ast }}$ is also a contraction. Indeed, for any $ 
u_{1},u_{2}\in \mathcal{X}_{T^{\ast },R^{\ast }}$, exploiting again (\ref 
{nonexp}), we estimate 
\begin{align}
\left\Vert \Sigma \left( u_{1}\left( t\right) \right) -\Sigma \left(
u_{2}\left( t\right) \right) \right\Vert _{\infty ,\Omega }& \leq
Q_{f^{^{\prime }}}\left( R^{\ast }\right) \int_{0}^{t}\left\Vert e^{-\left(
t-s\right) A_{\Theta ,\mu }}(u_{1}\left( s\right) -u_{2})\left( s\right)
\right\Vert _{\infty ,\Omega }ds  \label{3.21} \\
& \leq tQ_{f^{^{\prime }}}\left( R^{\ast }\right) \left\Vert
u_{1}-u_{2}\right\Vert _{C\left( \left[ 0,T^{\ast }\right] ;L^{\infty
}\left( \Omega \right) \right) }.  \notag
\end{align} 
This shows that $\Sigma $ is a contraction on $\mathcal{X}_{T^{\ast
},R^{\ast }}$ (compare with (\ref{3.21time})) provided that
\begin{equation*}
\max \left\{ \frac{2T^{\ast }(|f(0)|+Q_{f^{\prime }}(R^{\ast })R^{\ast })}{ 
R^{\ast }},T^{\ast }Q_{f^{\prime }}(R^{\ast })\right\} =\frac{2T^{\ast
}(|f(0)|+Q_{f^{\prime }}(R^{\ast }))R^{\ast }}{R^{\ast }}<1.
\end{equation*} 
Therefore, owing to the contraction mapping principle, we conclude that
problem (\ref{op_v}) has a unique local solution $u\in \mathcal{X}_{T^{\ast
},R^{\ast }}$. This solution can certainly be (uniquely) extended on a right
maximal time interval $[0,T_{\max })$, with $T_{\max }>0$ depending on $ 
\left\Vert u_{0}\right\Vert _{\infty ,\Omega },$ such that, either $T_{\max
}=\infty $ or $T_{\max }<\infty $, in which case $\lim_{t\nearrow T_{\max
}}\left\Vert u\left( t\right) \right\Vert _{\infty ,\Omega }=\infty .$
Indeed, if $T_{\max }<\infty $ and the latter condition does not hold, we
can find a sequence $t_{n}\nearrow T_{\max }$ such that $\left\Vert u\left(
t_{n}\right) \right\Vert _{\infty ,\Omega }\leq C.$ This would allow us to
extend $u$ as a solution to Equation (\ref{op_v}) to an interval $ 
[0,t_{n}+\delta ),$ for some $\delta >0$ independent of $n$. Hence $u$ can
be extended beyond $T_{\max }$ which contradicts the construction of $ 
T_{\max }>0$. To conclude that the solution $u$ belongs to the class in
Definition \ref{strong}, let us further set $\mathcal{G}\left( t\right)
:=-f\left( u\left( t\right) \right) ,$ for $u\in C\left( [0,T_{\max }\right)
;L^{\infty }\left( \Omega \right) )$ and notice that $u$ is the
"generalized" solution of 
\begin{equation}
\partial _{t}u+A_{\Theta ,\mu }u=\mathcal{G}\left( t\right) ,\text{ }t\in
\lbrack 0,T_{\max }),  \label{3.44}
\end{equation} 
such that $u\left( 0\right) =u_{0}\in L^{\infty }\left( \Omega \right)
\subset L^{2}(\Omega )=\overline{D(A_{\Theta ,\mu })}.$ By Theorem \ref{m1}
(Appendix), the "generalized" solution $u$ has the additional regularity $ 
\partial _{t}u\in L^{2}\left( \delta ,T_{\max };L^{2}\left( \Omega \right)
\right) ,$ which together with the facts that $u$ is continuous on $ 
[0,T_{\max })$ and $f\in C_{\text{loc}}^{1}\left( \mathbb{R}\right) $, yield
\begin{equation}
\mathcal{G}\in W^{1,2}\left( \delta ,T_{\max };L^{2}\left( \Omega \right)
\right) \cap L^{\infty }\left( \delta ,T_{\max };L^{2}\left( \Omega \right)
\right) .  \label{3.45}
\end{equation} 
Thus, we can apply Theorem \ref{ap_reg_thm} and Corollary \ref{ap_reg_co}
(see Appendix), to deduce the following regularity properties for $u:$ 
\begin{equation}
u\in L^{\infty }\left( [\delta ,T_{\max });D\left( A_{\Theta ,\mu }\right)
\right) \cap W^{1,\infty }\left( [\delta ,T_{\max });L^{2}\left( \Omega
\right) \right) ,  \label{3.46}
\end{equation} 
such that the solution $u$ is Lipschitz continuous on $[\delta ,T_{\max })$,
for every $\delta >0.$ Thus, we have obtained a locally-defined strong
solution in the sense of Definition \ref{strong}. As to the variational
equality in Definition \ref{weak}, we note that this equality is satisfied
even pointwise (in time $t\in \left( 0,T_{\max }\right) $) by the strong
solutions. Our final point is to show that $T_{\max }=\infty ,$ because of
condition (H1). This ensures that the strong solution constructed above is
also global.

\emph{Step 2} (Energy estimate) Let $m\geq 1$ and consider the function $ 
E_{m}:\;(0,\infty )\rightarrow \lbrack 0,\infty )$ defined by $ 
E_{m}(t):=\Vert u(t)\Vert _{m+1,\Omega }^{m+1}$. First, notice that $E_{m}$
is well-defined on $\left( 0,T_{\max }\right) $ because $u$ is bounded in $ 
\Omega \times (0,T_{\max })$ and because $\Omega $ has finite measure. Since
$u$ is a strong solution on $\left( 0,T_{\max }\right) ,$ see Definition \ref 
{strong} (or (\ref{3.46})), recall that $u$ is continuous from $[0,T_{\max
})\rightarrow L^{\infty }(\Omega )$ and Lipschitz continuous on $[\delta
,T_{\max })$ for every $\delta >0$. Thus, $u$ (as function of $t$) is
differentiable a.e., whence, the function $E_{m}(t)$ is also differentiable
for a.e. $t\in \left( 0,T_{\max }\right) .$

For strong solutions and $t\in \left( 0,T_{\max }\right) $, integration by
parts procedure yields the following standard energy identity: 
\begin{equation}
\frac{1}{2}\frac{d}{dt}E_{1}\left( t\right) +\mathcal{A}_{\Theta ,\mu
}\left( u\left( t\right) ,u\left( t\right) \right) +\int_{\Omega }f\left(
u\left( t\right) \right) u\left( t\right) dx=0.  \label{3.1}
\end{equation} 
Assumption (H1) implies that 
\begin{equation}
f\left( s\right) s\geq -\lambda _{\ast }s^{2}-C_{f},  \label{H1bis}
\end{equation} 
for some $C_{f}>0$ and for all $s\in \mathbb{R}$. This inequality allows us
to estimate the nonlinear term in (\ref{3.1}). We have (by using the
equivalent norm \eqref{eq-norm1})
\begin{equation}
\frac{1}{2}\frac{d}{dt}E_{1}\left( t\right) +C_{\Omega }\left\Vert u\left(
t\right) \right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega
,\mu )}^{2}\leq C_{f}\left\vert \Omega \right\vert +\lambda _{\ast
}E_{1}\left( t\right) ,  \label{3.2}
\end{equation} 
where $\left\vert \Omega \right\vert $ denotes the $N$-dimensional Lebesgue
measure of $\Omega .$ In view of \eqref{eq-norm1} and Gronwall's inequality,
(\ref{3.2}) gives the following estimate for $t\in \left( 0,T_{\max }\right)
,$ 
\begin{equation}
\left\Vert u\left( t\right) \right\Vert _{2,\Omega }^{2}+2\left( C_{\Omega
}-\lambda _{\ast }\right) \int_{0}^{t}\left\Vert u\left( s\right)
\right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
)}^{2}ds\leq \left\Vert u_{0}\right\Vert _{2,\Omega }^{2}e^{-\rho t}+C\left(
f,\left\vert \Omega \right\vert \right) ,  \label{3.3}
\end{equation} 
for some constants $\rho =\rho \left( N,\Omega \right) >0$, $C\left(
f,\left\vert \Omega \right\vert \right) >0.$

\emph{Step 3} (The iteration argument). In this step, $c>0$ will denote a
constant that is independent of $t,$ $T_{\max }$, $m,$ $k$ and initial data,
which only depends on the other structural parameters of the problem. Such a
constant may vary even from line to line. Moreover, we shall denote by $ 
Q_{\tau }\left( m\right) $ a monotone nondecreasing function in $m$ of order
$\tau ,$ for some nonnegative constant $\tau ,$ independent of $m.$ More
precisely, $Q_{\tau }\left( m\right) \sim cm^{\tau }$ as $m\rightarrow
+\infty .$ We begin by showing that $E_{m}\left( t\right) $ satisfies a
local recursive relation which can be used to perform an iterative argument.
Again standard procedure for the strong solutions on $\left( 0,T_{\max
}\right) $ (i.e., testing the variational equation (\ref{de_form}) with $ 
\left\vert u\right\vert ^{m-1}u,$ $m\geq 1;$ see, e.g., \cite[Lemma 9.3.1] 
{CD}, \cite[Theorem 3.2]{G} or \cite[Theorem 3.1]{Ali}) gives on account of ( 
\ref{H1bis})                         





the following inequality: 
\begin{eqnarray}
&&\frac{d}{dt}E_{m}\left( t\right) +\gamma \int_{\Omega }\left\vert \nabla
\left\vert u\right\vert ^{\frac{m+1}{2}}\right\vert ^{2}dx+\int_{\Gamma
_{\mu }}\left\vert u\right\vert ^{m+1}d\mu  \label{eqn1} \\
&\leq &Q_{1}\left( m+1\right) \left( E_{m}\left( t\right) +\left(
E_{m}\left( t\right) \right) ^{\frac{m}{m+1}}\right) ,  \notag
\end{eqnarray} 
for some constant $\gamma >0$ independent of $m,t$ and $T_{\max }$. Next,
set $m_{k}+1=2^{k},$ $k\in \mathbb{N}$, and define 
\begin{equation}
M_{k}:=\sup_{t\in \left( 0,T_{\max }\right) }\int_{\Omega }\left\vert
u\left( t,x\right) \right\vert ^{2^{k}}dx=\sup_{t\in \left( 0,T_{\max
}\right) }E_{m_{k}}\left( t\right) .  \label{def}
\end{equation} 
Our goal is to derive a recursive inequality for $M_{k}$ using (\ref{eqn1}).
In order to do so, we define 
\begin{equation*}
\overline{p}_{k}:=\frac{m_{k}-m_{k-1}}{q\left( 1+m_{k}\right) -\left(
1+m_{k-1}\right) }=\frac{1}{2q-1}<1,\text{ }\overline{q}_{k}:=1-\overline{p} 
_{k}=2\frac{q-1}{2q-1}
\end{equation*} 
since $q>1.$ We aim to estimate the terms on the right-hand side of (\ref 
{eqn1}) in terms of the $L^{1+m_{k-1}}\left( \Omega \right) $-norm of $u.$
First, H\"{o}lder inequality and Maz'ya inequality (i.e., $ 
W_{2,2}^{1}(\Omega ,\partial \Omega ,\mu )\subset L^{2q}\left( \Omega
\right) $, for some $q=q\left( N,\Omega \right) >1$, see (\ref{M2-N}) with $ 
q=N/\left( N-1\right) $ and $\mu =\sigma ,$ and (\ref{CI-mu}) when $\mu \neq
\sigma $) yield (by using the equivalent norm \eqref{eq-norm2}) 
\begin{align}
\int_{\Omega }\left\vert u\right\vert ^{1+m_{k}}dx& \leq \left( \int_{\Omega
}\left\vert u\right\vert ^{\left( 1+m_{k}\right) q}dx\right) ^{\overline{p} 
_{k}}\left( \int_{\Omega }\left\vert u\right\vert ^{1+m_{k-1}}dx\right) ^{ 
\overline{q}_{k}}  \label{ee5} \\
& \leq c\left( \int_{\Omega }\left\vert \nabla \left\vert u\right\vert ^{ 
\frac{\left( 1+m_{k}\right) }{2}}\right\vert ^{2}dx+\int_{\Gamma _{\mu
}}\left\vert u\right\vert ^{1+m_{k}}d\mu \right) ^{\overline{s}_{k}}\left(
\int_{\Omega }\left\vert u\right\vert ^{1+m_{k-1}}dx\right) ^{\overline{q} 
_{k}},  \notag
\end{align} 
with $\overline{s}_{k}=\overline{p}_{k}q\equiv q/\left( 2q-1\right) \in
\left( 0,1\right) $. Applying Young's inequality on the right-hand side of ( 
\ref{ee5}), we get for every $\varepsilon >0,$ 
\begin{eqnarray}
Q_{1}\left( m_{k}+1\right) \int_{\Omega }\left\vert u\right\vert
^{1+m_{k}}dx &\leq &\varepsilon \int_{\Omega }\left\vert \nabla \left\vert
u\right\vert ^{\frac{1+m_{k}}{2}}\right\vert ^{2}dx+\varepsilon \int_{\Gamma
_{\mu }}\left\vert u\right\vert ^{1+m_{k}}d\mu  \label{ee5bis} \\
&&+Q_{\alpha }\left( m_{k}+1\right) \left( \int_{\Omega }\left\vert
u\right\vert ^{1+m_{k-1}}dx\right) ^{\max \left\{ 2,z_{k}\right\} },  \notag
\end{eqnarray} 
for some $\alpha >0$ independent of $k$, where in fact $z_{k}:=\overline{q} 
_{k}/\left( 1-\overline{s}_{k}\right) \equiv 2$, for each $k$, since $ 
m_{k}+1\equiv 2^{k}$. In order to estimate the last term on the right-hand
side of (\ref{eqn1}), we define two decreasing and increasing sequences $ 
\left( l_{k}\right) _{k\in \mathbb{N}}$ and $\left( w_{k}\right) _{k\in
\mathbb{N}},$ respectively, such that 
\begin{equation*}
l_{k}=\frac{m_{k}+1}{\overline{s}_{k}m_{k}}\text{ and }w_{k}:=\frac{ 
\overline{q}_{k}m_{k}}{m_{k}\left( 1-\overline{s}_{k}\right) +1},
\end{equation*} 
and observe that they satisfy 
\begin{equation*}
1<l_{k}\leq 2\left( 2-\frac{1}{q}\right) ,\frac{2\left( q-1\right) }{3q-2} 
\leq w_{k}\leq 2
\end{equation*} 
for all $k\in \mathbb{N}$ (in particular, $w_{k}\rightarrow 2$ as $ 
k\rightarrow \infty $). The application of Young's inequality in (\ref 
{ee5bis}) yields again 
\begin{eqnarray}
Q_{1}\left( m_{k}+1\right) \left( \int_{\Omega }\left\vert u\right\vert
^{1+m_{k}}dx\right) ^{\frac{m_{k}}{m_{k}+1}} &\leq &\varepsilon \left(
\int_{\Omega }\left\vert \nabla \left\vert u\right\vert ^{\frac{1+m_{k}}{2} 
}\right\vert ^{2}dx+\int_{\Gamma _{\mu }}\left\vert u\right\vert
^{1+m_{k}}d\mu \right)  \label{ee5tris} \\
&&+Q_{\beta _{k}}\left( m_{k}+1\right) \left( \int_{\Omega }\left\vert
u\right\vert ^{1+m_{k-1}}dx\right) ^{w_{k}},  \notag
\end{eqnarray} 
for every $\varepsilon >0$, where now 
\begin{equation*}
Q_{\beta _{k}}\left( m_{k}+1\right) \sim \frac{c}{\varepsilon ^{1/\left(
l_{k}-1\right) }}\left( 1+m_{k}\right) ^{\beta _{k}}
\end{equation*} 
with $\beta _{k}:=\left( m_{k}+1\right) /\left( m_{k}\left( 1-\overline{s} 
_{k}\right) +1\right) \rightarrow \left( 2q-1\right) /\left( q-1\right) $,
as $k\rightarrow \infty $. Hence, inserting (\ref{ee5bis}), (\ref{ee5tris})
into equation (\ref{eqn1}), choosing a sufficiently small $0<\varepsilon
\leq \varepsilon _{0}:=\frac{1}{4}\min \left( \gamma ,1\right) $, and
simplifying, we obtain for $t\in \left( 0,T_{\max }\right) ,$ 
\begin{align}
& \frac{d}{dt}\int_{\Omega }\left\vert u\left( t,x\right) \right\vert
^{1+m_{k}}dx+\frac{\varepsilon _{0}}{2}\left( \int_{\Omega }\left\vert
\nabla \left\vert u\right\vert ^{\frac{1+m_{k}}{2}}\right\vert
^{2}dx+\int_{\Gamma _{\mu }}\left\vert u\right\vert ^{m_{k}+1}d\mu \right)
\label{ee6} \\
& \leq Q_{\delta }\left( m_{k}+1\right) \left( \int_{\Omega }\left\vert
u\right\vert ^{1+m_{k-1}}dx\right) ^{2},  \notag
\end{align} 
for some positive constant $\delta >0$ independent of $k.$

Next, we have $\left\vert u\right\vert ^{\frac{1+m_{k}}{2}}\in
W_{2,2}^{1}\left( \Omega ,\partial \Omega ,\mu \right) $ (recall that $ 
u\left( t\right) \in W_{2,2}^{1}\left( \Omega ,\partial \Omega ,\mu \right)
\cap L^{\infty }\left( \Omega \right) ,$ for a.e. $t\in \left( 0,T_{\max
}\right) $), so that by using the equivalent norm \eqref{eq-norm2}, we can
find another positive constant $c=c\left( \Omega ,N\right) $, depending on $ 
\Omega $ and $N,$ such that 
\begin{equation}
\int_{\Omega }\left\vert \nabla \left\vert u\right\vert ^{\frac{1+m_{k}}{2} 
}\right\vert ^{2}dx+\int_{\Gamma _{\mu }}\left\vert u\right\vert
^{m_{k}+1}d\mu \geq c\int_{\Omega }\left\vert u\right\vert ^{m_{k}+1}dx.
\label{ee6bis}
\end{equation} 
We can now combine (\ref{ee6bis}) with (\ref{ee6}) to deduce 
\begin{equation}
\frac{d}{dt}\int_{\Omega }\left\vert u\left( t,x\right) \right\vert
^{2^{k}}dx+\frac{c\varepsilon _{0}}{2}\int_{\Omega }\left\vert u\left(
t,x\right) \right\vert ^{2^{k}}dx\leq Q_{\delta }\left( 2^{k}\right)
M_{k-1}^{2},  \label{ee7bis}
\end{equation} 
for $t\in \left( 0,T_{\max }\right) .$ Integrating (\ref{ee7bis}) over $ 
\left( 0,t\right) $, we infer from Gronwall-Bernoulli's inequality \cite[ 
Lemma 1.2.4]{CD} that there exists yet another constant $c>0,$ independent
of $k$, such that 
\begin{equation}
M_{k}\leq \max \left\{ \int_{\Omega }\left\vert u_{0}\right\vert
^{2^{k}}dx,c2^{k\delta }M_{k-1}^{2}\right\} ,\text{ for all }k\geq 2.
\label{claim2}
\end{equation} 
On the other hand, let us observe that there exists a positive constant $ 
C_{\infty }=C_{\infty }(\left\Vert u_{0}\right\Vert _{\infty ,\Omega })\geq
1,$ independent of $k$, such that $\left\Vert u_{0}\right\Vert
_{2^{k},\Omega }\leq C_{\infty }$. Taking the $2^{k}$-th root on both sides
of (\ref{claim2}), and defining $X_{k}:=\sup_{t\in \left( 0,T_{\max }\right)
}\left\Vert u\left( t\right) \right\Vert _{2^{k},\Omega },$ we easily arrive
at 
\begin{equation}
X_{k}\leq \max \left\{ C_{\infty },\left( c2^{\delta k}\right) ^{\frac{1}{ 
2^{k}}}X_{k-1}\right\} ,\text{ for all }k\geq 2.  \label{ee7}
\end{equation} 
By straightforward induction in (\ref{ee7}) (see \cite[Lemma 3.2]{Ali}; cf.
also \cite[Lemma 9.3.1]{CD}), we finally obtain the estimate 
\begin{equation}
\sup_{t\in \left( 0,T_{\max }\right) }\left\Vert u\left( t\right)
\right\Vert _{\infty ,\Omega }\leq \lim_{k\rightarrow +\infty }X_{k}\leq
c\max \left\{ C_{\infty },\sup_{t\in \left( 0,T_{\max }\right) }\left\Vert
u\left( t\right) \right\Vert _{2,\Omega }\right\} .  \label{ee8}
\end{equation} 
It remains to notice that (\ref{ee8}) together with the bound (\ref{3.3})
shows that $\left\Vert u\left( t\right) \right\Vert _{\infty ,\Omega }$ is
uniformly bounded for all times $t>0$ with a bound, independent of $T_{\max
},$ depending only on $\left\Vert u_{0}\right\Vert _{\infty ,\Omega }$, the
"size" of the domain and the non-linear function $f.$ This gives $T_{\max
}=+\infty $ so that strong solutions are in fact global. This completes the
proof of the theorem.

\label{improved_reg}\emph{Strong solutions to Eqs. (\ref{1.1})--(\ref{1.3})
exhibit an improved regularity in time, we have} 
\begin{equation}
u\in C\left( \left[ 0,T\right] ;L^{\infty }\left( \Omega \right) \right)
\cap C((\delta ,T];\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
)),  \label{imp_reg}
\end{equation} 
\emph{for any }$T>\delta >0.$ \emph{This follows from the fact that the
nonlinear function }$f$\emph{\ is continuously differentiable. Note that the
second regularity in (\ref{imp_reg}) is a consequence of the first one, the
time regularity in (\ref{time_reg}) (see Definition \ref{strong}) and the
variational identity (}$\emph{\ref{de_form}}$\emph{).}

\label{dyn_sys_str}Let the assumptions of Theorem \ref{SG} be satisfied. The
reaction-diffusion system (\ref{1.1})-(\ref{1.3}) defines a (nonlinear)
continuous semigroup $\mathcal{T}\left( t\right) :L^{\infty }\left( \Omega
\right) \rightarrow L^{\infty }\left( \Omega \right) $, given by
\begin{equation}
\mathcal{T}\left( t\right) u_{0}=u\left( t\right) ,  \label{3.7}
\end{equation} 
where $u$ is the (unique)\ strong solution in the sense of Definition \ref 
{strong}.

We divide the proof into two main steps. For practical purposes, $C$ will
denote a positive constant that is independent of time, $T_{\ast }$, $ 
\epsilon >0$ and initial data, but which only depends on the other
structural parameters. Such a constant may vary even from line to line.

\emph{Step 1.} (The main energy estimate). Since $f$ obeys (H2), then (H1)
is satisfied and by Theorem \ref{SG}, the approximate problem (\ref{ap1})-( 
\ref{ap2}) has a strong solution that also satisfies the weak formulation ( 
\ref{de_form}). Thus, in view of (\ref{smooth}) the key choice $\xi
=u_{\epsilon }\left( t\right) $ in (\ref{de_form}) is justified. We have the
following energy identity 
\begin{equation}
\frac{1}{2}\frac{d}{dt}\left\Vert u_{\epsilon }\left( t\right) \right\Vert
_{2,\Omega }^{2}+\mathcal{A}_{\Theta ,\mu }\left( u_{\epsilon }\left(
t\right) ,u_{\epsilon }\left( t\right) \right) +\int_{\Omega }f\left(
u_{\epsilon }\left( t\right) \right) u_{\epsilon }\left( t\right) dx=0,
\notag
\end{equation} 
for all $t\in (0,T_{\ast }).$ Invoking assumption (H2), we infer 
\begin{equation}
\frac{1}{2}\frac{d}{dt}\left\Vert u_{\epsilon }\left( t\right) \right\Vert
_{2,\Omega }^{2}+C_{\Omega }\left\Vert u_{\epsilon }\left( t\right)
\right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
)}^{2}+\left\Vert u_{\epsilon }\left( t\right) \right\Vert _{p,\Omega
}^{p}\leq C\left\vert \Omega \right\vert  \label{3.5}
\end{equation} 
where we have used the equivalent norm \eqref{eq-norm1}. We can now
integrate this inequality over $\left( 0,T_{\ast }\right) $ to deduce 
\begin{equation}
\left\Vert u_{\epsilon }\left( t\right) \right\Vert _{2,\Omega
}^{2}+\int_{0}^{t}\left( C_{\Omega }\left\Vert u_{\epsilon }\left( s\right)
\right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
)}^{2}+C_{f}\left\Vert u_{\epsilon }\left( s\right) \right\Vert _{p,\Omega
}^{p}\right) ds\leq \left\Vert u_{\epsilon }\left( 0\right) \right\Vert
_{2,\Omega }^{2}e^{-\rho t}+C  \label{3.6}
\end{equation} 
for all $t\in \left( 0,T_{\ast }\right) ,$ for some $\rho >0$ independent of
$\epsilon >0$. Incidently, by (\ref{ap3}) this uniform estimate also shows
that we can take $T_{\ast }=\infty ,$ i.e., the weak solution that we
construct is in fact globally-defined. On account of (\ref{3.6}), we deduce
the following uniform (in $\epsilon >0$) bounds 
\begin{align}
u_{\epsilon }& \in L^{\infty }\left( 0,T;L^{2}\left( \Omega \right) \right)
\cap L^{p}\left( 0,T;L^{p}\left( \Omega \right) \right) ,  \label{est1} \\
u_{\epsilon }& \in L^{2}(0,T;\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial
\Omega ,\mu )),  \notag
\end{align} 
for any $T>0.$ Hence, by virtue of \eqref{op-star} and (\ref{est1}), we also
get 
\begin{equation}
A_{\Theta ,\mu }u_{\epsilon }\in L^{2}(0,T;(\mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu ))^{\ast }),\text{ }f\left( u_{\epsilon
}\right) \in L^{p^{^{\prime }}}(0,T;L^{p^{^{\prime }}}\left( \Omega \right)
),  \label{est2}
\end{equation} 
uniformly in $\epsilon >0$. Here, recall that $A_{\Theta ,\mu }$ is the
positive self-adjoint operator associated with the bilinear form $\mathcal{A} 
_{\Theta ,\mu }$ (see Section 2.2). By \eqref{op-star}, we can interpret ( 
\ref{de_form}) as the equality 
\begin{equation}
-\partial _{t}u_{\epsilon }=A_{\Theta ,\mu }u_{\epsilon }+f\left(
u_{\epsilon }\right)  \label{fform}
\end{equation} 
in $L^{2}(0,T;(\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
))^{\ast })+L^{p^{^{\prime }}}(0,T;L^{p^{^{\prime }}}\left( \Omega \right)
), $ where $p^{^{\prime }}=p/\left( p-1\right) $ (see also (\ref{op_v})).

\emph{Step 2.} (Passage to limit). From the above properties (\ref{est1})-( 
\ref{est2}), we see that there exists a subsequence $\left\{ u_{\epsilon
}\right\} _{\epsilon >0}$ (still denoted by $\left\{ u_{\epsilon }\right\} $ 
), such that as $\epsilon \rightarrow 0^{+}$, 
\begin{equation}
\begin{array}{l}
u_{\epsilon }\rightarrow u\text{ weakly star in }L^{\infty }\left(
0,T;L^{2}\left( \Omega \right) \right) , \\
u_{\epsilon }\rightarrow u\text{ weakly in }L^{p}\left( 0,T;L^{p}\left(
\Omega \right) \right) , \\
\partial _{t}u_{\epsilon }\rightarrow \partial _{t}u\text{ weakly in } 
L^{2}(0,T;(\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu ))^{\ast
})+L^{p^{^{\prime }}}(0,T;L^{p^{^{\prime }}}\left( \Omega \right) ). 
\end{array}
\label{2.27}
\end{equation} 
Since the continuous embedding $\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial
\Omega ,\mu )\hookrightarrow L^{2}\left( \Omega \right) $ is compact, then
we can exploit standard embedding results for vector valued functions (see,
e.g., \cite{CV}), to deduce 
\begin{equation}
u_{\epsilon }\rightarrow u\text{ strongly in }L^{2}\left( 0,T;L^{2}\left(
\Omega \right) \right) .  \label{2.30}
\end{equation} 
By refining in \eqref{2.30}, $u_{\epsilon }$ converges to $u$ a.e. in $ 
\Omega \times \left( 0,T\right) $. Then, by means of known results in
measure theory \cite{CV}, the continuity of $f$ and the convergence of  
\eqref{2.30} imply that $f\left( u_{\epsilon }\right) $ converges weakly to $ 
f\left( u\right) $ in $L^{p^{^{\prime }}}(\left( 0,T\right) \times \Omega )$ 
, while from (\ref{est1})-(\ref{est2}) and the linearity of $A_{\Theta ,\mu
} $, we further see that 
\begin{equation}
A_{\Theta ,\mu }u_{\epsilon }\rightarrow A_{\Theta ,\mu }u\text{ weakly in } 
L^{2}(0,T;(\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu ))^{\ast
}).  \label{2.32}
\end{equation} 
We can now pass to the limit as $\epsilon \rightarrow 0$ in equation (\ref 
{fform}) to deduce the desired weak solution $u$, satisfying the variational
identity (\ref{de_form}) and the regularity properties (\ref{reg_weak}). In
order to show the energy identity (\ref{en_id}), we can proceed in a
standard way as in \cite[Theorem II.1.8]{CV}, by observing that any
distributional derivative $\partial _{t}u\left( t\right) $ from $\mathcal{D} 
^{^{\prime }}(\left[ 0,T\right] ;(\mathcal{V}_{\Theta }^{1,2}(\Omega
,\partial \Omega ,\mu ))^{\ast }+ L^{p^{^{\prime }}}\left( \Omega \right) )$
can be represented as $\partial _{t}u\left( t\right) =\mathcal{Z}_{1}\left(
t\right) +\mathcal{Z}_{2}\left( t\right) ,$ where 
\begin{equation*}
\mathcal{Z}_{1}\left( t\right) :=-A_{\Theta ,\mu }u\left( t\right) \in
L^{2}(0,T;(\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu ))^{\ast
}),\text{ }\mathcal{Z}_{2}\left( t\right) :=-f\left( u\left( t\right)
\right) \in L^{p^{^{\prime }}}(0,T;L^{p^{^{\prime }}}\left( \Omega \right) ),
\end{equation*} 
which are precisely the dual of the spaces $L^{2}(0,T;(\mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu )))$, and $L^{p}(0,T;L^{p}\left( \Omega
\right) )$, respectively. In particular, we obtain that every weak solution $ 
u\in C\left( \left[ 0,T\right] ;L^{2}\left( \Omega \right) \right) ,$ and
that the map $t\mapsto \left\Vert u\left( t\right) \right\Vert _{2,\Omega
}^{2}$ is absolutely continuous on $\left[ 0,T\right] $, such that $u$
satisfies the energy identity 
\begin{equation}
\frac{1}{2}\frac{d}{dt}\left\Vert u\left( t\right) \right\Vert _{2,\Omega
}^{2}+\left\langle A_{\Theta ,\mu }u\left( t\right) ,u\left( t\right)
\right\rangle +\left\langle f\left( u\left( t\right) \right) ,u\left(
t\right) \right\rangle =0,  \label{en_id2}
\end{equation} 
a.e. $t\in \left[ 0,T\right] $, whence (\ref{en_id}) follows. The proof of
Theorem \ref{T1} is finished.

As usual, consider any two weak solutions $u_{1},u_{2},$ and set $u\left(
t\right) =u_{1}\left( t\right) -u_{2}\left( t\right) $. Then, according to ( 
\ref{en_id}) (cf. also (\ref{en_id2})), $u\left( t\right) $ satisfies the
identity 
\begin{equation*}
\frac{1}{2}\frac{d}{dt}\left\Vert u\left( t\right) \right\Vert _{2,\Omega
}^{2}+\mathcal{A}_{\Theta ,\mu }\left( u\left( t\right) ,u\left( t\right)
\right) =-\left\langle f\left( u_{1}\left( t\right) \right) -f\left(
u_{2}\left( t\right) \right) ,u\left( t\right) \right\rangle ,
\end{equation*} 
a.e. $t\in \left[ 0,T\right] .$ Assumption (H3) implies (by using the
equivalent norm \eqref{eq-norm1})
\begin{equation}
\frac{d}{dt}\left\Vert u\left( t\right) \right\Vert _{2,\Omega
}^{2}+C\left\Vert u\left( t\right) \right\Vert _{\mathcal{V} 
_{\Theta}^{1,2}(\Omega ,\partial \Omega ,\mu )}^{2}\leq 2C_{f}\left\Vert
u\left( t\right) \right\Vert _{2,\Omega }^{2}.  \label{3.8}
\end{equation} 
This yields the desired result by application of Gronwall's inequality.

\label{dyn_system}Let the assumptions of Proposition \ref{uniq} be
satisfied. The reaction-diffusion system (\ref{1.1})-(\ref{1.3}) defines a
(nonlinear) continuous semigroup $\mathcal{S}\left( t\right) :L^{2}\left(
\Omega \right) \rightarrow L^{2}\left( \Omega \right) $, given by
\begin{equation}
\mathcal{S}\left( t\right) u_{0}=u\left( t\right) ,  \label{2.15}
\end{equation} 
where $u$ is the (unique)\ weak solution in the sense of Definition \ref 
{weak}.

\label{bounded}Let the assumptions of Theorem \ref{SG} or Theorem \ref{T1}
be satisfied. Let $\tau ^{^{\prime }}>\tau >0$ and fix $\mu :=\tau
^{^{\prime }}-\tau $. There exists a positive constant $C=C\left( \mu
\right) \sim \mu ^{-\eta }$ (for some $\eta >0$), independent of $t$ and the
initial data, such that 
\begin{equation}
\sup_{t\geq \tau ^{^{\prime }}}\left\Vert u\left( t\right) \right\Vert
_{\infty ,\Omega }\leq C\sup_{s\geq \tau }\left\Vert u\left( s\right)
\right\Vert _{2,\Omega }.  \label{sup-b}
\end{equation}

The argument leading to (\ref{sup-b}) is analogous to \cite[Theorem 2.3]{G}
(cf. also \cite[Theorem 2.3]{GalNS}). It is based on the following recursive
inequality for $E_{m_{k}}\left( t\right) $, which is a consequence of (\ref 
{ee7bis}) and (\ref{ee5})-(\ref{ee6}): 
\begin{equation}
\sup_{t\geq t_{k-1}}E_{m_{k}}\left( t\right) \leq C\left( 2^{k}\right)
^{\delta }\left( \sup_{s\geq t_{k}}E_{m_{k-1}}\left( s\right) \right) ^{2}, 
\text{ \ for all }k\geq 1,  \label{rec_rel}
\end{equation} 
where the sequence $\left\{ t_{k}\right\} _{k\in \mathbb{N}}$ is defined
recursively $t_{k}=t_{k-1}-\mu /2^{k},$ $k\geq 1$, $t_{0}=\tau ^{^{\prime
}}. $ Here we recall that $C=C\left( \mu \right) >0,$ $\delta >0$ are
independent of $k.$ For the sake of completeness, we report a sketch of the
argument for (\ref{rec_rel}). To this end, let $\zeta \left( s\right) $ be a
positive function $\zeta :\mathbb{R}_{+}\rightarrow \left[ 0,1\right] $ such
that $\zeta \left( s\right) =0$ for $s\in \left[ 0,t-\mu /2^{k}\right] ,$ $ 
\zeta \left( s\right) =1$ if $s\in \left[ t,+\infty \right) $ and $ 
\left\vert d\zeta /ds\right\vert \leq 2^{k}/\mu $, if $s\in \left( t-\mu
/2^{k},t\right) $. We define $Z_{k}\left( s\right) =\zeta \left( s\right)
E_{m_{k}}\left( s\right) $ and notice that 
\begin{align}
\frac{d}{ds}Z_{k}\left( s\right) & \leq \zeta \left( s\right) \frac{d}{ds} 
E_{m_{k}}\left( s\right) +\frac{2^{k}}{\mu }E_{m_{k}}\left( s\right)
\label{e11bis} \\
& =\zeta \left( s\right) \frac{d}{ds}E_{m_{k}}\left( s\right) +Q_{1}\left(
2^{k}\right) \int_{\Omega }\left\vert u\right\vert ^{1+m_{k}}dx.  \notag
\end{align} 
The last integral in (\ref{e11bis}) can be estimated as in (\ref{ee5bis})
and (\ref{ee6bis}). Combining the above estimates and the fact that $ 
Z_{k}\leq E_{m_{k}}$, we deduce the following inequality: 
\begin{equation}
\frac{d}{ds}Z_{k}\left( s\right) +C2^{k}Z_{k}\left( s\right) \leq C\left(
2^{k}\right) ^{\sigma }(\sup_{s\geq t-\mu /2^{k}}E_{m_{k-1}}\left( s\right)
)^{2},\text{ for all }s\in \left[ t-\mu /2^{k},+\infty \right) .  \label{e12}
\end{equation} 
Note that $C=C\left( \mu \right) \sim \mu ^{-1}$ as $\mu \rightarrow 0$, and
$C\left( \mu \right) $ is bounded if $\mu $ is bounded away from zero.
Integrating (\ref{e12}) with respect to $s$ from $t-\mu /2^{k}$ to $t,$ and
taking into account the fact that $Z_{k}\left( t-\mu /2^{k}\right) =0,$ we
obtain that $E_{m_{k}}\left( t\right) =Z_{k}\left( t\right) \leq C\left(
2^{k}\right) ^{\sigma }(\sup_{s\geq t-\mu /2^{k}}E_{m_{k-1}}\left( s\right)
)^{2}\left( 1-e^{-C\mu }\right) $, which proves the claim (\ref{rec_rel}).
Thus, we can iterate in (\ref{rec_rel}) with respect to $k\geq 1$ and obtain
that 
\begin{align}
\sup_{t\geq t_{k-1}}E_{m_{k}}\left( t\right) & \leq \left( C\left(
2^{k}\right) ^{\delta }\right) \left( C\left( 2^{k-1}\right) ^{\delta
}\right) ^{2}\cdot ...\cdot \left( C\left( 2\right) ^{\delta }\right)
^{2^{k}}(\sup_{s\geq \tau }\left\Vert u\left( s\right) \right\Vert
_{2,\Omega })^{2^{k}}  \label{3.9} \\
& \leq C^{\left( 2^{k}\sum_{i=1}^{k}\frac{1}{2^{i}}\right) }2^{\left( \delta
2^{k}\sum_{i=1}^{k}\frac{i}{2^{i}}\right) }(\sup_{s\geq \tau }\left\Vert
u\left( s\right) \right\Vert _{2,\Omega })^{2^{k}},  \notag
\end{align} 
Therefore, we can take the $1+m_{k}=2^{k}$-th root on both sides of (\ref 
{3.9}) and let $k\rightarrow +\infty $. Using the facts that $\zeta
:=\sum_{i=1}^{\infty }\frac{1}{2^{i}}<\infty ,$ $\overline{\zeta } 
:=\sum_{i=1}^{\infty }\frac{i}{2^{i}}<\infty $, we deduce 
\begin{equation}
\sup_{t\geq t_{0}=\tau ^{^{\prime }}}\left\Vert u\left( t\right) \right\Vert
_{\infty ,\Omega }\leq \lim_{k\rightarrow +\infty }\sup_{t\geq t_{0}}\left(
E_{m_{k}}\left( t\right) \right) ^{1/\left( 1+m_{k}\right) }\leq C^{\zeta
}2^{\delta \overline{\zeta }}\sup_{s\geq \tau }\left\Vert u\left( s\right)
\right\Vert _{2,\Omega }.  \notag
\end{equation} 
This clearly proves the proposition.

\label{h1est}Let the assumptions of Proposition \ref{uniq} be satisfied.
Then, for $u_{0}\in L^{2}\left( \Omega \right) $ any orbit $u\left( t\right)
=\mathcal{S}\left( t\right) u_{0}$ of (\ref{1.1})-(\ref{1.3}) satisfies 
\begin{equation*}
u\in L^{\infty }([\rho ,\infty );\mathcal{V}_{\Theta }^{1,2}(\Omega
,\partial \Omega ,\mu ))\cap W^{1,2}\left( [\rho ,\infty );L^{2}\left(
\Omega \right) \right) ,
\end{equation*} 
for every $\rho >0$, and the following estimate holds: 
\begin{equation}
\sup_{t\geq \rho }\left( \left\Vert u\left( t\right) \right\Vert _{\mathcal{V 
}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )}^{2}+\int_{0}^{t}\left\Vert
\partial _{t}u\left( s\right) \right\Vert _{2,\Omega }^{2}ds\right) \leq
C_{\delta },  \label{as_sm}
\end{equation} 
for some constant $C_{\delta }=C\left( \rho \right) >0,$ independent of $t$
and initial data.

We recall that by Theorem \ref{3prop}, $A_{\Theta ,\mu }$ is a positive and
self-adjoint operator in $L^{2}\left( \Omega \right) $. Then, we have a
complete system of eigenfunctions $\left\{ \xi _{i}\right\} _{i\in \mathbb{N} 
}$ for the operator $A_{\Theta ,\mu }$ in $L^{2}\left( \Omega \right) $ with
$\xi _{i}\in D\left( A_{\Theta ,\mu }\right) \subset \mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu ),$ and $\xi _{i}\in L^{\infty }\left(
\Omega \right) .$ According to the general spectral theory, the eigenvalues $ 
\lambda _{i}$ can be increasingly ordered and counted according to their
multiplicities in order to form a real divergent sequence. Moreover, the
respective eigenvectors $\xi _{i}$ turn out to form an orthogonal basis in $ 
\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )$ and $L^{2}\left(
\Omega \right) ,$ respectively. The eigenvectors $\xi _{i}$ may be assumed
to be normalized in $L^{2}\left( \Omega \right) $. To this end, we can now
define the finite-dimensional spaces
\begin{equation*}
\mathcal{P}_{n}=span\left\{ \xi _{1},\xi _{2},...,\xi _{n}\right\} ,\quad
\mathcal{P}_{\infty }=\cup _{n=1}^{\infty }\mathcal{P}_{n}.
\end{equation*} 
Clearly, $\mathcal{P}_{\infty }$ is a dense subspace of $\mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu )$. As usual, for any $n\in \mathbb{N}$ 
, we look for functions of the form 
\begin{equation}
u_{n}(t)=\sum_{i=1}^{n}e_{i}\left( t\right) \xi _{i}  \label{Proj}
\end{equation} 
solving a suitable approximating problem. More precisely, for any given $ 
n\geq 1$ we look for $C^{1}$-real functions $e_{i}\left( \cdot \right) $, $ 
i=1,\dots ,n$, only depending on time, which solve the approximating problem
$\mathbf{P}\left( n\right) $ given by
\begin{equation}
\left( \partial _{t}u_{n},\Psi \right) _{2,\Omega }+\left( A_{\Theta ,\mu
}u_{n},\Psi \right) _{2,\Omega }+\left( f\left( u_{n}\right) ,\Psi \right)
_{2,\Omega }=0,  \label{Approx_p}
\end{equation} 
with initial condition 
\begin{equation}
\left\langle u_{n}\left( 0\right) ,\Psi \right\rangle _{2,\Omega
}=\left\langle u_{n0},\Psi \right\rangle _{2,\Omega },  \label{Approx_IC}
\end{equation} 
for all $\Psi \in \mathcal{P}_{n}.$ Here $u_{n0}$ is the orthogonal
projection of $u_{0}$ onto $\mathcal{P}_{n}.$ Observe that
\begin{equation}
\underset{n\rightarrow \infty }{\lim }u_{n0}=u_{0},\quad \text{ in } 
L^{2}\left( \Omega \right) \text{.}  \label{IC_limit}
\end{equation}

Notice that by the Cauchy-Lipschitz theorem, one can find a unique maximal
solution 
\begin{equation*}
u_{n}\in C^{1}([0,T_{n});D\left( A_{\Theta ,\mu }\right) \cap L^{\infty
}\left( \Omega \right) )
\end{equation*} 
to (\ref{Approx_p})-(\ref{Approx_IC}), for some $T_{n}\in (0,T)$. As in the
case when $\Omega $ is smooth (see the monographs \cite{BV, CV, R, T}), the
existence of a generalized solution, defined on the whole interval $[0,T],$
for every $n\in \mathbb{N}$, can be also obtained with this approach. In
particular, notice that (\ref{3.6}) is also satisfied by $u_{n}$. Here we
are interested to derive the bound (\ref{as_sm}). Notice that the key choice
of the test function $\xi =\partial _{t}u_{n}\in $ $C([0,T];\mathcal{V} 
_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )\cap L^{p}\left( \Omega
\right) )$ into the variational equation (\ref{de_form}) is now allowed for
these truncated solutions. We deduce 
\begin{equation*}
\frac{d}{dt}\left( \left\Vert u_{n}\left( t\right) \right\Vert _{\mathcal{V} 
_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )}^{2}+\left( F\left(
u_{n}\left( t\right) \right) ,1\right) _{2,\Omega }\right) +2\left\Vert
\partial _{t}u_{n}\left( t\right) \right\Vert _{2,\Omega }^{2}=0,
\end{equation*} 
for all $t\geq 0.$ Here and below, $F$ denotes the primitive of $f$, i.e., $ 
F\left( s\right) =\int_{0}^{s}f\left( y\right) dy.$ Multiply this equation
by $t\geq \rho >0$ and integrate over $\left( 0,t\right) $ to get 
\begin{align*}
& t\left( \left\Vert u_{n}\left( t\right) \right\Vert _{\mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu )}^{2}+\left( F\left( u_{n}\left(
t\right) \right) ,1\right) _{2,\Omega }\right) +2\int_{0}^{t}s\left\Vert
\partial _{t}u_{n}\left( s\right) \right\Vert _{2,\Omega }^{2}ds \\
& =\int_{0}^{t}\left( \left\Vert u_{n}\left( s\right) \right\Vert _{\mathcal{ 
V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )}^{2}+\left( F\left(
u_{n}\left( s\right) \right) ,1\right) _{2,\Omega }\right) ds,
\end{align*} 
for all $t\geq \rho .$ Recalling that, due to (H2)-(H3), $F$ is bounded from
below, independently of $n$, and $\left\vert F\left( s\right) \right\vert
\leq C\left( 1+\left\vert s\right\vert ^{p}\right) $, we infer from (\ref 
{3.6}), 
\begin{equation}
\left\Vert u_{n}\left( t\right) \right\Vert _{\mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu )}^{2}+2\int_{0}^{t}\left\Vert \partial
_{t}u_{n}\left( s\right) \right\Vert _{2,\Omega }^{2}ds\leq c\left( 1+\frac{1 
}{t}\right) ,  \label{as_sm2}
\end{equation} 
for some constant $c>0$ independent of $t,n$ and $\rho .$ On the basis of a
lower-semicontinuity argument, we easily obtain the desired estimate (\ref 
{as_sm}). The proof is finished.

\label{gl_notion}A set $\mathcal{G}_{\Theta ,\mu }\subset L^{2}\left( \Omega
\right) $ is a global attractor of the semigroup $\mathcal{S}\left( t\right)
$ on $L^2(\Omega)$ associated with (\ref{1.1})-(\ref{1.3}) if

\begin{itemize}
\item $\mathcal{G}_{\Theta ,\mu }$ is compact in $L^{2}\left( \Omega \right)
$;

\item $\mathcal{G}_{\Theta ,\mu }$ is strictly invariant, that is, $\mathcal{ 
S}(t)\mathcal{G}_{\Theta ,\mu }=\mathcal{G}_{\Theta ,\mu }\;\forall\; t\ge 0$ 
;

\item $\mathcal{G}_{\Theta ,\mu }$ attracts the images of all bounded
subsets of $L^{2}\left( \Omega \right) $, namely, for every bounded subset $ 
B $ of $L^{2}\left( \Omega \right) $ and every neighborhood $\mathcal{O}$ of
$\mathcal{G}_{\Theta ,\mu }$ in the topology of $L^{2}\left( \Omega \right) $ 
, there exists a constant $T=T(B;\mathcal{O})>0$ such that $\mathcal{S} 
(t)B\subset \mathcal{O}$, for every $t\geq T$.
\end{itemize}

Due to the dissipative estimates (\ref{3.6}), (\ref{sup-b}) and (\ref{as_sm} 
), the ball 
\begin{equation*}
\mathcal{B}_{0}=\left\{ u\in \mathcal{X}:=L^{\infty }\left( \Omega \right)
\cap \mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu ):\left\Vert
u\right\Vert _{\mathcal{X}}\leq R\right\} ,
\end{equation*} 
for a sufficiently large radius $R>0,$ is an absorbing set for $\mathcal{S} 
\left( t\right) $ in $L^{2}\left( \Omega \right) $. Indeed, in light of (\ref 
{3.6}), it is not difficult to see that, for any bounded set $B\subset
L^{2}\left( \Omega \right) $, there exists a time $t_{\ast }=t_{\ast }(B)>0$
such that $\mathcal{S}\left( t\right) B\subset L^{2}\left( \Omega \right) $,
for all $t\geq t_{\ast }$. Next, we can choose $\tau ^{^{\prime }}=\tau
+2\mu $ with $\tau =t_{\ast }$ and $\mu =1$, so that the $L^{2}$-$L^{\infty
} $ smoothing property (\ref{sup-b}) together with the estimate (\ref{as_sm} 
) entails the desired assertion. Obviously, the ball $\mathcal{B}_{0}$ is
compact in the topology of $L^{2}\left( \Omega \right) $. Thus, $\mathcal{S} 
\left( t\right) $ possesses a compact absorbing set. On the other hand, due
to Proposition \ref{uniq} (see also (\ref{diffbis}) below), for every fixed $ 
t\geq 0$, the map $\mathcal{S}\left( t\right) $ is continuous on $\mathcal{B} 
_{0}$ in the $L^{2}$-topology and, consequently, the existence of the global
attractor follows now from the classical attractor's existence theorem (see,
e.g. \cite{CV}).

\label{L2}Make the assumptions of Corollary \ref{weak-strong} (or Theorem  
\ref{SG}). Then the functional 
\begin{equation*}
\mathcal{L}_{\Theta }\left( u(t)\right) :=\frac{1}{2}\left\Vert u\left(
t\right) \right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega
,\mu )}^{2}+\left( F\left( u\left( t\right) \right) ,1\right) _{2,\Omega },
\end{equation*} 
has along the strong solutions of (\ref{1.1})-(\ref{1.3}), the derivative 
\begin{equation*}
\frac{d}{dt}\mathcal{L}_{\Theta }\left( u\left( t\right) \right)
=-\int_{\Omega }\left\vert \partial _{t}u\left( t\right) \right\vert ^{2}dx, 
\text{ }a.e.\text{ }t>0.
\end{equation*} 
In other words, the functional $\mathcal{L}_{\Theta }$ is decreasing, and
becomes stationary exactly on equilibria $u_{\ast }$, which are solutions of
the system: 
\begin{equation}
-\Delta u+f\left( u\right) =0\text{ in }\Omega ,\text{ }\partial _{\nu
}ud\sigma +(u+\Theta_\mu \left( u\right) )d\mu =0\text{ on }\partial \Omega .
\label{equi}
\end{equation}

\begin{enumerate}
\item[(i)] Any $\omega$-limit set $\Lambda _{L^{2}}^{+}$ is nonempty,
compact and connected.

\item[(ii)] The trajectory approaches its own limit set in the norm of $ 
L^{2}\left( \Omega \right) $, i.e.,
\begin{equation*}
\lim_{t\rightarrow \infty }dist_{L^{2}\left( \Omega \right) }\left( \mathcal{ 
S}\left( t\right) u_{0},\Lambda _{L^{2}}^{+}\right) =0.
\end{equation*}

\item[(iii)] Any $\omega $-limit set is invariant: new trajectories which
start at some point in $\Lambda _{L^{2}}^{+}$ remain in $\Lambda
_{L^{2}}^{+} $ for all times $t>0$.
\end{enumerate}

\label{abstract}Let $\mathcal{H}$,$\mathcal{V}$,$\mathcal{V}_{1}$ be Banach
spaces such that the embedding $\mathcal{V}_{1}\hookrightarrow \mathcal{V}$
is compact. Let $\mathbb{B}$ be a closed bounded subset of $\mathcal{H}$ and
let $\mathbb{S}:\mathbb{B}\rightarrow \mathbb{B}$ be a map. Assume also that
there exists a uniformly Lipschitz continuous map $\mathbb{T}:\mathbb{B} 
\rightarrow \mathcal{V}_{1}$, i.e., 
\begin{equation}
\left\Vert \mathbb{T}b_{1}-\mathbb{T}b_{2}\right\Vert _{\mathcal{V}_{1}}\leq
L\left\Vert b_{1}-b_{2}\right\Vert _{\mathcal{H}},\quad \forall
b_{1},b_{2}\in \mathbb{B},  \label{gl1}
\end{equation} 
for some $L\geq 0$, such that 
\begin{equation}
\left\Vert \mathbb{S}b_{1}-\mathbb{S}b_{2}\right\Vert _{\mathcal{H}}\leq
\gamma \left\Vert b_{1}-b_{2}\right\Vert _{\mathcal{H}}+K\left\Vert \mathbb{T 
}b_{1}-\mathbb{T}b_{2}\right\Vert _{\mathcal{V}},\quad \forall
b_{1},b_{2}\in \mathbb{B},  \label{gl2}
\end{equation} 
for some constant $0\le \gamma <\frac{1}{2}$ and $K\geq 0$. Then, there
exists a (discrete) exponential attractor $\mathcal{M}_{d}\subset \mathbb{B}$
of the semigroup $\{\mathbb{S}(n):=\mathbb{S}^{n},n\in \mathbb{Z}_{+}\}$
with discrete time in the phase space $\mathcal{H}$, which satisfies the
following properties:

\begin{itemize}
\item semi-invariance: $\mathbb{S}\left( \mathcal{M}_{d}\right) \subset
\mathcal{M}_{d}$;

\item compactness: $\mathcal{M}_{d}$ is compact in $\mathcal{H}$;

\item exponential attraction: $dist_{\mathcal{H}}(\mathbb{S}^{n}\mathbb{B}, 
\mathcal{M}_{d})\leq Ce^{-\alpha n},$ for all $n\in \mathbb{N}$ and for some
$\alpha >0$ and $C\geq 0$, where $dist_{\mathcal{H}}$ denotes the standard
Hausdorff semidistance between sets in $\mathcal{H}$;

\item finite-dimensionality: $\mathcal{M}_{d}$ has finite fractal dimension
in $\mathcal{H}$.
\end{itemize}

\label{expo}Assume that the nonlinearity $f$\ obeys (H2)-(H3) and $\mu $
satisfies (H$_{\mu }$). The semigroup $\mathcal{S}\left( t\right) $ on $ 
L^{2}(\Omega )$ associated with (\ref{1.1})-(\ref{1.3}) possesses an
exponential attractor $\mathcal{E}_{\Theta ,\mu }$ in the following sense:

\begin{itemize}
\item $\mathcal{E}_{\Theta ,\mu }$ is bounded in $L^{\infty }\left( \Omega
\right) \cap \mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )$ and
compact in $L^{2}\left( \Omega \right) $;

\item $\mathcal{E}_{\Theta ,\mu }$ is semi-invariant: $\mathcal{S}\left(
t\right) \left( \mathcal{E}_{\Theta ,\mu }\right) \subset \mathcal{E} 
_{\Theta ,\mu }$, $t\geq 0$;

\item $\mathcal{E}_{\Theta ,\mu }$ attracts the images of bounded (in $ 
L^{2}\left( \Omega \right) $) subsets exponentially in the metric of $ 
L^{\infty }\left( \Omega \right) $, i.e. there exist $\beta >0$ and a
monotone function $Q$ such that, for every bounded set $B\subset L^{2}\left(
\Omega \right) $, 
\begin{equation*}
dist_{L^{\infty }\left( \Omega \right) }\left( \mathcal{S}\left( t\right) B, 
\mathcal{E}_{\Theta ,\mu }\right) \leq Q\left( \left\Vert B\right\Vert
_{L^{2}\left( \Omega \right) }\right) e^{-\beta t},\text{ for all }t\geq 0 
\text{;}
\end{equation*}

\item $\mathcal{E}_{\Theta ,\mu }$ has the finite fractal dimension in $ 
L^{\infty }\left( \Omega \right) $.
\end{itemize}

\label{gl_fin}The fractal dimension of the global attractor $\mathcal{G} 
_{\Theta ,\mu }$ of Proposition \ref{glatt} is finite in $L^{\infty }\left(
\Omega \right) $. Moreover, we have 
\begin{equation*}
\lim_{t\rightarrow +\infty }dist_{L^{\infty }\left( \Omega \right) }\left(
\mathcal{S}\left( t\right) B,\mathcal{G}_{\Theta ,\mu }\right) =0,
\end{equation*} 
for every bounded set $B\subset L^{2}\left( \Omega \right) .$

\label{L5}Let the assumptions of Theorem \ref{expo} hold, and let $u_{1}$
and $u_{2}$ be two weak solutions of (\ref{1.1})-(\ref{1.3}) such that $ 
u_{i}\left( 0\right) \in \mathcal{B}_{0}.$ Then the following estimates are
valid: 
\begin{equation}
\left\Vert u_{1}\left( t\right) -u_{2}\left( t\right) \right\Vert _{2,\Omega
}^{2}\leq M\left\Vert u_{1}\left( 0\right) -u_{2}\left( 0\right) \right\Vert
_{2,\Omega }^{2}e^{-\omega t}+K\left\Vert u_{1}-u_{2}\right\Vert
_{L^{2}\left( \left[ 0,t\right] ;L^{2}\left( \Omega \right) \right) }^{2},
\label{diff1}
\end{equation} 
and
\begin{equation}
\left\Vert \partial _{t}u_{1}-\partial _{t}u_{2}\right\Vert _{L^{2}(\left[
0,t\right] ;(\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
))^{\ast })}^{2}+\int_{0}^{t}\left\Vert u_{1}\left( s\right) -u_{2}\left(
s\right) \right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega
,\mu )}^{2}ds\leq Ce^{\nu t}\left\Vert u_{1}\left( 0\right) -u_{2}\left(
0\right) \right\Vert _{2,\Omega }^{2},  \label{diff2}
\end{equation} 
for some $\omega ,\nu >0,$ $M,K,C\geq 0,$ all independent of $t$ and $u_{i}.$

The injection $\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
)\hookrightarrow L^{2}\left( \Omega \right) $ is compact and continuous. The
application of Gronwall's inequality in (\ref{3.8}) entails the desired
estimate (\ref{diff1}). The second term on the left-hand side of (\ref{diff2} 
) can be easily controlled by integration over $\left( 0,t\right) $ in (\ref 
{3.8}). More precisely, we have 
\begin{equation}
\left\Vert u_{1}\left( t\right) -u_{2}\left( t\right) \right\Vert _{2,\Omega
}^{2}+\int_{0}^{t}\left\Vert u_{1}\left( s\right) -u_{2}\left( s\right)
\right\Vert _{\mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu
)}^{2}ds\leq \left\Vert u_{1}\left( 0\right) -u_{2}\left( 0\right)
\right\Vert _{2,\Omega }^{2}e^{\nu t}.  \label{diffbis}
\end{equation} 
Furthermore, in light of Corollary \ref{weak-strong} and estimates (\ref 
{sup-b}), (\ref{h1est}), recall that we have 
\begin{equation}
\sup_{t\geq 0}\left\Vert u_{i}\left( t\right) \right\Vert _{L^{\infty
}\left( \Omega \right) \cap \mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial
\Omega ,\mu )}\leq C,  \label{4.5}
\end{equation} 
for some positive constant $C$ independent of $t$ and $u_{i}$. Thus, for any
test function $\xi $ $\in \mathcal{V}_{\Theta }^{1,2}(\Omega ,\partial
\Omega ,\mu )$, using the variational identity (\ref{de_form}) (which
actually holds pointwise for $t\geq 0$), we have for the function $ 
u:=u_{1}-u_{2},$ 
\begin{align*}
\left\langle \partial _{t}u\left( t\right) ,\xi \right\rangle & =-\mathcal{A} 
_{\Theta ,\mu }\left( u\left( t\right) ,\xi \right) -\left\langle f\left(
u_{1}\left( t\right) \right) -f\left( u_{2}\left( t\right) \right) ,\xi
\right\rangle \\
& \leq C\left\Vert u\left( t\right) \right\Vert _{\mathcal{V}_{\Theta
}^{1,2}(\Omega ,\partial \Omega ,\mu )}\left\Vert \xi \right\Vert _{\mathcal{ 
V}_{\Theta }^{1,2}(\Omega ,\partial \Omega ,\mu )},
\end{align*} 
since $f\in C_{\text{loc}}^{1}\left( \mathbb{R}\right) $, owing to (\ref{4.5} 
). This estimate together with (\ref{diffbis}) gives the desired control on
the time derivative in (\ref{diff2}).

\label{time_cont}Let the assumptions of Theorem \ref{expo} be satisfied.
Consider $u\left( t\right) =\mathcal{S}\left( t\right) u_{0}$ with $u_{0}\in
\mathcal{B}_{0}$. Then, for every $t\geq 0$, the following estimate holds: 
\begin{equation}
\left\Vert u\left( t\right) -u\left( s\right) \right\Vert _{\infty ,\Omega
}\leq C\left\vert t-s\right\vert ^{\lambda },\text{ for all }t,s\geq 0,
\label{4.6}
\end{equation} 
where $\lambda <1$, $C>0$ are independent of $t,s$, $u$ and the initial data.

\label{expo2}Assume that the nonlinearity $f$\ obeys (H1) and $\mu $
satisfies (H$_{\mu }$). The semigroup $\mathcal{T}\left( t\right) $ on $ 
L^{\infty }(\Omega )$ associated with strong solutions of (\ref{1.1})-(\ref 
{1.3}) possesses an exponential attractor $\mathcal{Y}_{\Theta ,\mu }$ in
the following sense:

\begin{itemize}
\item $\mathcal{Y}_{\Theta ,\mu }$ is bounded in $L^{\infty }\left( \Omega
\right) \cap D\left( A_{\Theta ,\mu }\right) $ and compact in $L^{2}\left(
\Omega \right) $;

\item $\mathcal{Y}_{\Theta ,\mu }$ is semi-invariant: $\mathcal{T}\left(
t\right) \left( \mathcal{Y}_{\Theta ,\mu }\right) \subset \mathcal{Y} 
_{\Theta ,\mu }$, $t\geq 0$;

\item $\mathcal{Y}_{\Theta ,\mu }$ attracts the images of bounded (in $ 
L^{\infty }\left( \Omega \right) $) subsets exponentially in the metric of $ 
L^{\infty }\left( \Omega \right) $, i.e. there exist $\beta >0$ and a
monotone function $Q$ such that, for every bounded set $B\subset L^{\infty
}\left( \Omega \right) $, 
\begin{equation*}
dist_{L^{\infty }\left( \Omega \right) }\left( \mathcal{T}\left( t\right) B, 
\mathcal{Y}_{\Theta ,\mu }\right) \leq Q\left( \left\Vert B\right\Vert
_{L^{\infty }\left( \Omega \right) }\right) e^{-\beta t},\text{ for all } 
t\geq 0\text{;}
\end{equation*}

\item $\mathcal{Y}_{\Theta ,\mu }$ has the finite fractal dimension in $ 
L^{\infty }\left( \Omega \right) .$
\end{itemize}

\label{SGbis} Let $\Omega \subset {\mathbb{R}}^{N}$ be an arbitrary open set
with finite measure and assume that $\mu $ satisfies (H$_{\mu }$). Then the
subgradient $-\partial \varphi _{\Theta ,\mu }(=-A_{\Theta ,\mu })$
generates a strongly continuous (linear) semigroup $\left\{ e^{-tA_{\Theta
,\mu }}\right\} _{t\geq 0}$ of contractions on $L^{2}(\Omega )$. In
particular, for every $u_{0}\in L^{2}(\Omega )$, the orbit $ 
u(t)=e^{-tA_{\Theta ,\mu }}u_{0}$ is the unique strong solution of the first
order Cauchy problem 
\begin{equation}
\partial _{t}u\left( t,x\right) +\partial \varphi _{\Theta _{\mu }}\left(
u\left( t,x\right) \right) =0,\;\;\left( t,x\right) \in \mathbb{R}_{+}\times
\Omega ,\;\;u_{\mid t=0}=u_{0}\text{ in }\Omega ,  \label{C-pro}
\end{equation} 
such that 
\begin{equation*}
u\in C([0,\infty );L^{2}(\Omega ))\cap W_{\text{loc}}^{1,\infty }((0,\infty
);L^{2}(\Omega ))\;\mbox{ and }\;u(t,\cdot )\in D(A_{\Theta ,\mu })\text{,
a.e. on }\left( 0,\infty \right) .
\end{equation*} 
Moreover, the (linear) semigroup $\left\{ e^{-tA_{\Theta ,\mu }}\right\}
_{t\geq 0}$ is non-expansive on $L^{\infty }(\Omega )$ in the sense that 
\begin{equation}
\Vert e^{-tA_{\Theta ,\mu }}u_{0}\Vert _{\infty ,\Omega }\leq \left\Vert
u_{0}\right\Vert _{\infty ,\Omega },  \label{sup-nonexp}
\end{equation} 
for every $t\geq 0$ and $\,u_{0}\in L^{\infty }(\Omega ).$

\label{m1}Let $\varphi :H\rightarrow (-\infty,+\infty] $ be a proper,
convex, and lower-semicontinuous functional on the Hilbert space $H$ and set
$A=\partial \varphi .$ Let $u$ be the generalized solution of 
\begin{equation}
\left\{
\begin{array}{ll}
u^{\prime}(t)+A\left( u\right) \ni g\left( t\right) , & t\in \left[ 0,T 
\right] , \\
u_{\mid t=0}=u_{0}\text{,} &
\end{array} 
\right.  \label{nonhom}
\end{equation} 
with $g\in L^{2}\left( 0,T;H\right) $ and $u_{0}\in \overline{D\left(
A\right) }.$ Then $\varphi \left( u\right) \in L^{1}\left( 0,T\right) ,$ $ 
\sqrt{t}u^{\prime}(t)\in L^{2}\left( 0,T;H\right) $ and $u\left( t\right)
\in D\left( A\right) $ for a.e. $t\in \left[ 0,T\right] .$

\label{ap_reg_thm}Let the assumptions of Theorem \ref{m1} be satisfied.
Assume that $A=\partial \varphi $ is \emph{strongly} accretive in $H$, that
is, $A-\omega I$ is accretive for some $\omega >0$ and, in addition, 
\begin{equation*}
g\in L^{\infty }\left( [\delta ,\infty );H\right) \cap W^{1,2}\left( [\delta
,\infty );H\right) ,
\end{equation*} 
for every $\delta >0$. Let $u$ be the generalized solution of (\ref{nonhom})
for $u_{0}\in \overline{D\left( A\right) }$. It follows that $u\left(
t\right) \in D\left( A\right) ,$ $t\geq \delta >0$, and the following
estimate holds for some $v\in D\left( A\right) $: 
\begin{equation}
\left\Vert A^{0}u\left( t\right) \right\Vert _{H}\leq C\left( \left\Vert
A^{0}v\right\Vert _{H}+\frac{1}{\delta }\left\Vert u_{0}-v\right\Vert
_{H}+\left\Vert g\right\Vert _{L^{\infty }\left( [\delta ,\infty );H\right)
}+\left\Vert g^{^{\prime }}\right\Vert _{L^{2}\left( [\delta ,\infty
);H\right) }\right) ,  \label{append1}
\end{equation} 
for each $u_{0}\in \overline{D\left( A\right) }$ and $t\geq \delta >0.$ The
constant $C>0$ is independent of $t,\delta ,u,v,u_{0}$ and $g.$ Here $A^{0}$
denotes the minimal section of $A$.

We proceed as follows. We first regularize the solution $u$ by a sequence of
approximate solutions $u_{\alpha }$ with $\alpha >0$, in which $u_{\alpha
}\in C^{1}\left( \left[ 0,T\right] ;H\right) $ such that $u_{\alpha }\left(
0\right) =u_{0}\in \overline{D\left( A\right) }$, and $u_{\alpha }$ solves
the following regularized problem 
\begin{equation}
u_{\alpha }^{\prime }\left( t\right) +A_{\alpha }\left( u_{\alpha }\left(
t\right) \right) =g_{\alpha }\left( t\right) ,\text{ }t\in \left[ 0,T\right]
.  \label{reg_app}
\end{equation} 
Here $A_{\alpha }$ corresponds to the Yosida approximation of $A$, and $ 
g_{\alpha }\in C^{1}\left( \left[ 0,T\right] ;H\right) $ is a sequence of
approximate functions such that, as $\alpha \rightarrow 0^{+},$ 
\begin{equation}
g_{\alpha }\rightarrow g\text{ in }L^{\infty }\left( 0,T;H\right) \cap
W^{1,2}\left( 0,T;H\right) .  \label{reg_app2}
\end{equation} 
Note that by \cite[Chapter IV, Proposition 1.8]{Scho} we have $A_{\alpha
}=\varphi _{\alpha }^{^{\prime }},$ $\alpha >0,$ i.e., $A_{\alpha }$ is
Lipschitz continuous. Hence by the standard Cauchy-Lipschitz theorem, there
exists at least one solution $u_{\alpha }\in C^{1}\left( \left[ 0,T\right]
;H\right) $ to problem (\ref{reg_app}).

\emph{Step 1.} If $h>0$, then $u_{\alpha }\left( t+h\right) $ is a solution
of (\ref{reg_app}) with $g_{\alpha }\left( t\right) $ replaced by $g_{\alpha
}\left( t+h\right) $, and the accretive estimate on $A_{\alpha }$ (i.e., $ 
\left( A_{\alpha }w_{1}-A_{\alpha }w_{2},w_{1}-w_{2}\right) _{H}\geq \omega
\left\Vert w_{1}-w_{2}\right\Vert _{H}^{2},$ $\omega >0$) gives 
\begin{align*}
& \frac{1}{2}\frac{d}{dt}\left\Vert u_{\alpha }\left( t+h\right) -u_{\alpha
}\left( t\right) \right\Vert _{H}^{2}+\omega \left\Vert u_{\alpha }\left(
t+h\right) -u_{\alpha }\left( t\right) \right\Vert _{H}^{2} \\
& \leq \left\Vert g_{\alpha }\left( t+h\right) -g_{\alpha }\left( t\right)
\right\Vert _{H}\left\Vert u_{\alpha }\left( t+h\right) -u_{\alpha }\left(
t\right) \right\Vert _{H} \\
& \leq \frac{1}{2}\left( \omega \left\Vert u_{\alpha }\left( t+h\right)
-u_{\alpha }\left( t\right) \right\Vert _{H}^{2}+\frac{1}{\omega }\left\Vert
g_{\alpha }\left( t+h\right) -g_{\alpha }\left( t\right) \right\Vert
_{H}^{2}\right) .
\end{align*} 
Thus, for $0\leq s\leq t$ we get, on account of Gronwall's inequality (see,
e.g., \cite[Chapter IV, Lemma 4.1]{Scho}), 
\begin{equation*}
\left\Vert u_{\alpha }\left( t+h\right) -u_{\alpha }\left( t\right)
\right\Vert _{H}^{2}e^{\omega t}\leq \left\Vert u_{\alpha }\left( s+h\right)
-u_{\alpha }\left( s\right) \right\Vert _{H}^{2}e^{\omega s}+\omega
^{-1}\int_{s}^{t}e^{\omega \tau }\left\Vert g_{\alpha }\left( \tau +h\right)
-g_{\alpha }\left( \tau \right) \right\Vert _{H}^{2}d\tau .
\end{equation*} 
Dividing both sides of this inequality by $h^{2}$, then letting $ 
h\rightarrow 0^{+}$, we obtain after standard transformations, 
\begin{align}
\left\Vert u_{\alpha }^{^{\prime }}\left( t\right) \right\Vert _{H}^{2}&
\leq \left\Vert u_{\alpha }^{^{\prime }}\left( s\right) \right\Vert
_{H}^{2}e^{-\omega \left( t-s\right) }+\omega ^{-1}\int_{s}^{t}e^{-\omega
\left( t-\tau \right) }\left\Vert g_{\alpha }^{^{\prime }}\left( \tau
\right) \right\Vert _{H}^{2}d\tau  \label{esta10} \\
& \leq \left\Vert u_{\alpha }^{^{\prime }}\left( s\right) \right\Vert
_{H}^{2}+\omega ^{-1}\int_{s}^{t}\left\Vert g_{\alpha }^{^{\prime }}\left(
\tau \right) \right\Vert _{H}^{2}d\tau ,  \notag
\end{align} 
for all $t\geq s\geq 0.$

\emph{Step 2}. Fix now $v\in H$ and $\alpha >0$, and define 
\begin{equation*}
\psi \left( w\right) =\varphi _{\alpha }\left( w\right) -\varphi_\alpha
\left( v\right) -\left( A_{\alpha }v,w-v\right) _{H},\text{ }w\in H.
\end{equation*} 
Note that $\psi ^{^{\prime }}\left( w\right) =\varphi _{\alpha }^{^{\prime
}}\left( w\right) -A_{\alpha }v$, $w\in H,$ $\min_{w\in H}\psi \left(
w\right) =\psi \left( v\right) =0$, and
\begin{equation*}
u_{\alpha }^{\prime}\left( t\right) +\psi ^{^{\prime }}\left( u_{\alpha
}\left( t\right) \right) =-A_{\alpha }v+g_{\alpha }\left( t\right) ,\text{ } 
t\in \left[ 0,T\right] .
\end{equation*} 
Since $\left( \psi ^{^{\prime }}\left( u_{\alpha }\right) ,v-u_{\alpha
}\right) _{H}\leq \psi \left( v\right) -\psi \left( u_{\alpha }\right)
=-\psi \left( u_{\alpha }\right) $, it follows that 
\begin{align*}
\psi \left( u_{\alpha }\left( t\right) \right) & \leq \left( u_{\alpha
}^{^{\prime }}\left( t\right) +A_{\alpha }v-g_{\alpha }\left( t\right)
,v-u_{\alpha }\left( t\right) \right) _{H} \\
& =-\frac{1}{2}\frac{d}{dt}\left\Vert v-u_{\alpha }\left( t\right)
\right\Vert _{H}^{2}+\left( A_{\alpha }v,v-u_{\alpha }\left( t\right)
\right) _{H} -\left( g_{\alpha }\left( t\right) ,v-u_{\alpha }\left(
t\right) \right) _{H}.
\end{align*} 
Hence, by integration over $\left( 0,T\right) $ we deduce 
\begin{align}
& \int_{0}^{T}\left( \psi \left( u_{\alpha }\left( t\right) \right) +\left(
A_{\alpha }v,u_{\alpha }\left( t\right) -v\right) _{H}+\left( g_{\alpha
}\left( t\right) ,v-u_{\alpha }\left( t\right) \right) _{H}\right) dt
\label{esta11} \\
& \leq \frac{1}{2}\left( \left\Vert v-u_{0}\right\Vert _{H}^{2}-\left\Vert
v-u_{\alpha }\left( T\right) \right\Vert _{H}^{2}\right) .  \notag
\end{align} 
This is the energy estimate. In order to estimate the derivative of $ 
u_{\alpha }$, we take the scalar product in $H$ of equation (\ref{reg_app})
with $u_{\alpha }^{^{\prime }}$, multiply the resulting identity by $t\geq 0$ 
, to deduce 
\begin{align}
& t\left\Vert u_{\alpha }^{^{\prime }}\left( t\right) \right\Vert _{H}^{2}+ 
\frac{d}{dt}\left[ t\left( \psi \left( u_{\alpha }\left( t\right) \right)
+\left( A_{\alpha }v,u_{\alpha }\left( t\right) -v\right) _{H}+\left(
g_{\alpha }\left( t\right) ,v-u_{\alpha }\left( t\right) \right) _{H}\right)  
\right]  \label{esta12} \\
& =\psi \left( u_{\alpha }\left( t\right) \right) +\left( A_{\alpha
}v,u_{\alpha }\left( t\right) -v\right) _{H}+\left( g_{\alpha }\left(
t\right) ,v-u_{\alpha }\left( t\right) \right) _{H}.  \notag
\end{align} 
Integrating over $\left( 0,T\right) $ and combining with the energy estimate
(\ref{esta11}), on account of Young's inequality, we obtain 
\begin{equation}
\int_{0}^{T}t\left\Vert u_{\alpha }^{^{\prime }}\left( t\right) \right\Vert
_{H}^{2}dt\leq \frac{1}{2}\left( \left\Vert v-u_{0}\right\Vert
_{H}^{2}+T^{2}\left\Vert A_{\alpha }v\right\Vert _{H}^{2}+T^{2}\left\Vert
g_{\alpha }\left( T\right) \right\Vert _{H}^{2}\right) .  \label{esta13}
\end{equation} 
The $H$-norm of $u_{\alpha }^{^{\prime }}\left( t\right) $ satisfies (\ref 
{esta10}) with $t=T$ and $s=t$, so the left-hand side of (\ref{esta13})
dominates 
\begin{equation}
\frac{T^{2}}{2}\left\Vert u_{\alpha }^{^{\prime }}\left( T\right)
\right\Vert _{H}^{2}-\omega ^{-1}\int_{0}^{T}t\int_{t}^{T}\left\Vert
g_{\alpha }^{^{\prime }}\left( \tau \right) \right\Vert _{H}^{2}d\tau dt.
\label{esta14}
\end{equation} 
We obtain from (\ref{esta13}) and (\ref{esta14}), for each $0<\delta \leq
t\leq T$, 
\begin{equation*}
\frac{T^{2}}{2}\left\Vert u_{\alpha }^{^{\prime }}\left( T\right)
\right\Vert _{H}^{2}\leq \frac{1}{2}\left( \left\Vert v-u_{0}\right\Vert
_{H}^{2}+T^{2}\left\Vert A_{\alpha }v\right\Vert _{H}^{2}+T^{2}\left\Vert
g_{\alpha }\left( T\right) \right\Vert _{H}^{2}+\omega ^{-1}\frac{T^{2}}{2} 
\left\Vert g_{\alpha }^{^{\prime }}\right\Vert _{L^{2}\left( \delta
,T;H\right) }^{2}\right) ,
\end{equation*} 
which coupled together with the basic inequality $\left( a-b\right) ^{2}\geq
\frac{a^{2}}{2}-b^{2}$, and equation (\ref{reg_app}), yield 
\begin{equation}
\frac{T^{2}}{4}\left\Vert A_{\alpha }\left( u_{\alpha }\left( t\right)
\right) \right\Vert _{H}^{2}\leq \frac{1}{2}\left( \left\Vert
v-u_{0}\right\Vert _{H}^{2}+T^{2}\left\Vert A_{\alpha }v\right\Vert
_{H}^{2}+2T^{2}\left\Vert g_{\alpha }\left( T\right) \right\Vert
_{H}^{2}+\omega ^{-1}\frac{T^{2}}{2}\left\Vert g_{\alpha }^{^{\prime
}}\right\Vert _{L^{2}\left( \delta ,T;H\right) }^{2}\right) .  \label{esta15}
\end{equation} 
Finally, by virtue of (\ref{reg_app2}), we deduce the following bound for $ 
A_{\alpha }\left( u_{\alpha }\right) $ in $L^{\infty }\left( \delta
,T;H\right) $: 
\begin{equation}
\left\Vert A_{\alpha }\left( u_{\alpha }\left( T\right) \right) \right\Vert
_{H}^{2}\leq \frac{2}{T^{2}}\left\Vert v-u_{0}\right\Vert
_{H}^{2}+2\left\Vert A^{0}v\right\Vert _{H}^{2}+4\left\Vert g\left( T\right)
\right\Vert _{H}^{2}+2\omega ^{-1}\left\Vert g^{^{\prime }}\right\Vert
_{L^{2}\left( \delta ,T;H\right) }^{2},  \label{esta16}
\end{equation} 
for every $\alpha >0$ and $T\geq \delta >0.$ Arguing now in a standard way
(see the proof of \cite[Chapter IV, Proposition 3.1]{Scho}), we can pass to
the limit as $\alpha \rightarrow 0$ in (\ref{esta16}), along a subsequence $ 
\alpha _{n}\rightarrow 0$, $A_{\alpha _{n}}\left( u_{\alpha _{n}}\left(
T\right) \right) \rightarrow y\in A\left( u\left( T\right) \right) $, so
that (\ref{append1}) follows from (\ref{esta16}) by the weak
lower-semicontinuity of the norm. This completes the proof of the theorem.
